import Darwin
import Foundation

private enum ProjectText {
    static let excludedDirs: Set<String> = [
        "node_modules", "bower_components", "vendor", "pods", "carthage", "deriveddata", "build", "dist",
        "out", "target", "obj", "coverage", "venv", "__pycache__", "__macosx", "generated",
        "autogenerated", "third_party", "third-party", "xcuserdata"
    ]
    static func skipDirectory(_ name: String) -> Bool {
        let name = name.lowercased()
        return name.hasPrefix(".") || excludedDirs.contains(name) || name.hasSuffix(".app") || name.hasSuffix(".framework")
            || name.hasSuffix(".xcframework") || name.hasSuffix(".dsym") || name.hasSuffix(".xcresult")
    }

    // Make git prune common untracked output trees before they enter its file list.
    static let gitExcludes = (excludedDirs.sorted() + [".*", "Pods", "DerivedData", "Carthage", "*.app",
                                                        "*.framework", "*.xcframework", "*.dSYM", "*.xcresult"])
        .map { "--exclude=\($0)/" }

    private static let excludedNames: Set<String> = [
        "package-lock.json", "npm-shrinkwrap.json", "pnpm-lock.yaml", "go.sum", "go.work.sum",
        "package.resolved", "bun.lockb"
    ]
    private static let excludedExtensions = words("""
        lock sum csv tsv jsonl ndjson parquet arrow log map dump sqlite sqlite3 db
        png jpg jpeg gif webp avif bmp tif tiff ico icns svgz pdf ai psd
        mp3 mp4 flac mov m4a mkv wav aiff heic zip gz tgz bz2 xz tar 7z rar
        jar war class pyc o a so dylib dll exe wasm dmg pkg ttf otf woff woff2
        doc docx xls xlsx ppt pptx
        """)
    private static let textExtensions = words("""
        swift m mm c cc cpp cxx h hh hpp hxx cs fs fsx vb rs go mod java kt kts groovy gradle
        sh bash zsh fish ps1 bat cmd py pyi rb erb php pl pm lua r jl dart ex exs erl hrl
        scala clj cljs cljc hs lhs ml mli nim zig sol asm s f f90 v sv vhd elm
        js jsx cjs mjs ts tsx mts cts css scss sass less styl html htm vue svelte astro
        md mdx markdown txt rst adoc asciidoc tex org ipynb json jsonc yaml yml toml xml
        ini cfg conf properties plist entitlements strings stringsdict xcconfig xcscheme pbxproj
        csproj fsproj vbproj sln props targets cmake mk bzl bazel nix dockerfile tf tfvars hcl
        sql gql graphql proto prisma thrift scpt applescript awk patch diff
        """)
    private static let textNames = words("""
        readme license licence copying changelog authors notice contributing dockerfile containerfile
        makefile gnumakefile cmakelists.txt gemfile rakefile podfile brewfile fastfile justfile jenkinsfile
        pipfile procfile vagrantfile build workspace
        """)
    private static let textDirs = words("""
        src source sources lib include bin script scripts tools test tests spec doc docs
        documentation config configs configuration manifests internal cmd app
        """)
    private static func words(_ string: String) -> Set<String> {
        Set(string.split(whereSeparator: \.isWhitespace).map(String.init))
    }

    enum Candidate { case recognized, inspectShebang }

    static func candidate(name: String, directories: [String]) -> Candidate? {
        let name = name.lowercased()
        let ext = name.split(separator: ".").last.map(String.init) ?? ""
        guard !name.hasPrefix("."), !excludedNames.contains(name), !excludedExtensions.contains(ext),
              !name.hasSuffix(".min.js"), !name.hasSuffix(".min.css"), !name.hasSuffix(".pb.go"),
              !name.hasSuffix("_pb2.py"), !name.hasSuffix("_pb2_grpc.py"),
              !name.contains(".generated."), !name.hasSuffix(".g.cs"), !name.hasSuffix(".g.dart") else { return nil }
        if textNames.contains(name) || (name.contains(".") && textExtensions.contains(ext))
            || name.hasPrefix("dockerfile.") || name.hasPrefix("readme.")
            || directories.contains(where: textDirs.contains) {
            return .recognized
        }
        // A script can have any suffix and live outside the usual source directories.
        return .inspectShebang
    }

    static func include(header: String, candidate: Candidate) -> Bool {
        if candidate == .inspectShebang && !header.hasPrefix("#!") { return false }
        if header.hasPrefix("version https://git-lfs.github.com/spec/v1") { return false }
        for line in header.prefix(4096).split(whereSeparator: \.isNewline).prefix(24) {
            let text = line.trimmingCharacters(in: .whitespaces).lowercased()
            if text.hasPrefix("-- postgresql database dump") || text.hasPrefix("-- mysql dump")
                || text.hasPrefix("-- mariadb dump") { return false }
            if text.hasPrefix("//") || text.hasPrefix("#") || text.hasPrefix("/*")
                || text.hasPrefix("*") || text.hasPrefix("<!--") || text.hasPrefix("--") {
                if text.contains("@generated") || text.contains("<auto-generated")
                    || text.contains("automatically generated") || text.contains("auto-generated")
                    || (text.contains("generated") && text.contains("do not edit")) { return false }
            }
        }
        return true
    }
}

final class LineGroup: NSObject, Sendable {
    let name: String
    let lines: Int
    let children: [LineGroup]

    init(_ name: String, lines: Int, children: [LineGroup] = []) {
        self.name = name
        self.lines = lines
        self.children = children
    }
}

struct ProjectLineCount {
    var lines = 0
    var issues = FileIssues()
    let isDirectory: Bool
    private(set) var groups: [LineGroup] = []

    private final class DirectoryContents {
        private var directories: [String: DirectoryContents] = [:]
        private var files: [LineGroup] = []

        func directory(at path: ArraySlice<Substring>) -> DirectoryContents {
            var current = self
            for component in path {
                let name = String(component)
                if let existing = current.directories[name] {
                    current = existing
                } else {
                    let child = DirectoryContents()
                    current.directories[name] = child
                    current = child
                }
            }
            return current
        }

        func addFile(named name: String, lines: Int) {
            files.append(LineGroup(name, lines: lines))
        }

        func groups() -> [LineGroup] {
            let folders = directories.map { name, directory in
                let children = directory.groups()
                return LineGroup(name, lines: children.reduce(0) { $0 + $1.lines }, children: children)
            }
            return (folders + files).sorted(by: ProjectLineCount.byName)
        }
    }

    private static func byName(_ lhs: LineGroup, _ rhs: LineGroup) -> Bool {
        let order = lhs.name.localizedStandardCompare(rhs.name)
        return order == .orderedSame ? lhs.name < rhs.name : order == .orderedAscending
    }

    static func count(_ url: URL) throws -> Self {
        guard !url.lastPathComponent.hasPrefix(".") else {
            throw FileToolError("点号开头的隐藏文件和目录不计入统计。")
        }
        let values = try url.resourceValues(forKeys: [.isDirectoryKey, .isSymbolicLinkKey])
        guard values.isSymbolicLink != true else { throw FileToolError("请选择文件或目录本身。") }
        guard values.isDirectory == true else {
            guard let file = try DirectoryFiles.regularFile(at: url.path, in: AT_FDCWD, flags: O_NOFOLLOW),
                  let lines = try TextLines.count(file) else { throw FileToolError("所选文件不是文本文件。") }
            return Self(lines: lines, isDirectory: false)
        }

        var result = Self(isDirectory: true)
        let contents = DirectoryContents()
        let repository = repositoryRoot(for: url)
        let context = repository.map { Array(url.pathComponents.dropFirst($0.pathComponents.count)) }
            ?? [url.lastPathComponent]
        func addDirectory(_ path: String) {
            _ = contents.directory(at: path.split(separator: "/")[...])
        }
        func add(_ parent: Int32, file: String, path: String) throws {
            let parts = path.split(separator: "/")
            guard let name = parts.last else { return }
            let dirs = context + parts.dropLast().map(String.init)
            guard !dirs.contains(where: ProjectText.skipDirectory),
                  let candidate = ProjectText.candidate(name: String(name), directories: dirs.map { $0.lowercased() }),
                  let handle = try DirectoryFiles.regularFile(at: file, in: parent) else { return }
            if let lines = try TextLines.count(handle, includeHeader: { ProjectText.include(header: $0, candidate: candidate) }) {
                contents.directory(at: parts.dropLast()).addFile(named: String(name), lines: lines)
            }
        }
        if repository != nil {
            try DirectoryFiles.walk(url, skipDirectory: ProjectText.skipDirectory,
                                    visitDirectory: addDirectory,
                                    onError: { result.issues.record($0, $1) }, visit: { _, _, _ in })
            let parent = open(url.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard parent >= 0 else { throw DirectoryFiles.systemError() }
            defer { close(parent) }
            try gitFiles(in: url, warning: { result.issues.record(url.lastPathComponent, FileToolError($0)) }) { path in
                do { try add(parent, file: path, path: path) }
                catch let error as NSError where error.domain == NSPOSIXErrorDomain
                    && [Int(ENOENT), Int(ENOTDIR)].contains(error.code) {
                    // The index can still contain removed files or a directory replaced by a file.
                } catch { result.issues.record(path, error) }
            }
        } else {
            try DirectoryFiles.walk(url, skipDirectory: ProjectText.skipDirectory,
                                    visitDirectory: addDirectory,
                                    onError: { result.issues.record($0, $1) }, visit: add)
        }
        result.groups = contents.groups()
        result.lines = result.groups.reduce(0) { $0 + $1.lines }
        return result
    }

    private static func repositoryRoot(for url: URL) -> URL? {
        var current = url.standardizedFileURL
        while current.path != "/" {
            if FileManager.default.fileExists(atPath: current.appendingPathComponent(".git").path) { return current }
            current.deleteLastPathComponent()
        }
        return nil
    }

    private static func gitFiles(in root: URL, warning: (String) -> Void, visit: (String) -> Void) throws {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/git")
        process.arguments = ["--no-optional-locks", "-c", "core.fsmonitor=false", "-C", root.path,
                             "ls-files", "--cached", "--others", "--exclude-standard", "--deduplicate", "-z"]
            + ProjectText.gitExcludes + ["--", "."]
        let output = Pipe()
        process.standardOutput = output
        // Drain stdout while git runs. A separate diagnostic stream prevents a warning from
        // becoming a filename and avoids blocking git when it reports many unreadable paths.
        guard let diagnostics = tmpfile() else { throw DirectoryFiles.systemError() }
        defer { fclose(diagnostics) }
        let errors = FileHandle(fileDescriptor: fileno(diagnostics), closeOnDealloc: false)
        process.standardError = errors
        try process.run()
        var pending = Data()
        while let chunk = try output.fileHandleForReading.read(upToCount: 65536), !chunk.isEmpty {
            pending.append(chunk)
            while let end = pending.firstIndex(of: 0) {
                if let path = String(data: pending[..<end], encoding: .utf8) { visit(path) }
                else { warning("有文件名无法读取。") }
                pending = pending.suffix(from: end + 1)
            }
        }
        process.waitUntilExit()
        try errors.seek(toOffset: 0)
        let detail = String(decoding: try errors.read(upToCount: 2048) ?? Data(), as: UTF8.self)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard process.terminationStatus == 0 else {
            throw FileToolError(detail.isEmpty ? "Git 未能读取所选目录。" : detail)
        }
        if !detail.isEmpty { warning(detail) }
    }
}
